package com.onebytelabs.zlplay;
import android.content.*;import android.graphics.*;import android.net.Uri;import org.json.*;import java.util.*;import java.io.*;
/** Private Android library and overrides; never rewrites desktop projects. */
public final class RepertoireLibrary {
 private final Context context;private final SharedPreferences prefs;
 public RepertoireLibrary(Context context){this.context=context;this.prefs=context.getSharedPreferences("android-library",0);}
 public JSONArray entries(){try{return new JSONArray(prefs.getString("entries","[]"));}catch(JSONException e){return new JSONArray();}}
 public static String key(String tree,String file){return tree+"|"+file;}
 public void remember(String tree,String file,String title){try{JSONArray old=entries(),next=new JSONArray();JSONObject row=new JSONObject().put("tree",tree).put("file",file).put("title",title);boolean found=false;for(int i=0;i<old.length();i++){JSONObject entry=old.getJSONObject(i);if(key(tree,file).equals(key(entry.getString("tree"),entry.getString("file")))){next.put(row);found=true;}else next.put(entry);}if(!found)next.put(row);prefs.edit().putString("entries",next.toString()).apply();}catch(JSONException e){throw new IllegalStateException(e);}}
 public void saveOrder(String key,java.util.List<com.onebytelabs.zlplay.project.SetlistSpec.Song> songs){JSONArray order=new JSONArray();for(var song:songs)order.put(song.id);prefs.edit().putString("order:"+key,order.toString()).apply();}
 public void applyOrder(String key,java.util.List<com.onebytelabs.zlplay.project.SetlistSpec.Song> songs){try{JSONArray order=new JSONArray(prefs.getString("order:"+key,"[]"));List<com.onebytelabs.zlplay.project.SetlistSpec.Song> sorted=new ArrayList<>();Map<String,com.onebytelabs.zlplay.project.SetlistSpec.Song> map=new LinkedHashMap<>();for(var song:songs)map.put(song.id,song);for(int i=0;i<order.length();i++){var song=map.remove(order.getString(i));if(song!=null)sorted.add(song);}sorted.addAll(map.values());songs.clear();songs.addAll(sorted);}catch(JSONException ignored){}}
 public File coverFile(String key){try{byte[] digest=java.security.MessageDigest.getInstance("SHA-256").digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder name=new StringBuilder();for(byte b:digest)name.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return new File(new File(context.getFilesDir(),"covers"),name+".png");}catch(Exception e){throw new IllegalStateException(e);}}
 public static Bitmap decode(Context context,Uri uri)throws IOException{byte[] bytes;try(InputStream in=context.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[8192];int n;while((n=in.read(block))!=-1){if(out.size()+n>8*1024*1024)throw new IOException("Image too large");out.write(block,0,n);}bytes=out.toByteArray();}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<=0||options.outHeight<=0)throw new IOException("Invalid image");options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>512)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap image=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(image==null)throw new IOException("Invalid image");return image;}
 public Bitmap importCover(String key,Uri uri)throws IOException{Bitmap image=decode(context,uri);File file=coverFile(key);if(!file.getParentFile().isDirectory()&&!file.getParentFile().mkdirs())throw new IOException();File temp=File.createTempFile("cover-",".tmp",file.getParentFile());try{try(FileOutputStream out=new FileOutputStream(temp)){if(!image.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException();}android.system.Os.rename(temp.getAbsolutePath(),file.getAbsolutePath());return image;}catch(Exception e){temp.delete();throw new IOException(e);}}
}
